ee:message.ee:set-payload:
%dw 2.0
output application/json
import try from dw::Runtime
import resolve from dw::Timezones

var rawCity = vars.arguments.city default ""
var timezone = resolve(rawCity)
var attempt = try(() -> now() >> (timezone as TimeZone))
---
if (attempt.success)
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "result": {
        "content": [
            {
                "type": "text",
                "text": (attempt.result as String {format: "EEEE, MMMM d, yyyy h:mm:ss a"})
                        ++ " " ++ (attempt.result as String {format: "z"})
                        ++ " (" ++ timezone ++ ")"
            }
        ]
    }
}
else
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "error": {
        "code": -32602,
        "message": "Unknown city or timezone: '" ++ rawCity ++ "'. Use a supported city name or an IANA timezone ID (e.g. 'America/New_York')."
    }
}
